const e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Une vérification rapide en lecture seule pour s'assurer que l'imprimante est prête à lancer une impression."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Revérifier"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Vérification…"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"Prête à imprimer"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"Pas prête à imprimer"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"L'imprimante est injoignable"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper est prêt"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper n'est pas prêt (état : "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Aucune impression en cours"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Une impression est déjà en cours ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Tous les axes sont à l'origine"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Axes non pris en origine ("},{t:4,k:"axes"},{t:3,v:") ; un lancement d'impression effectue généralement la prise d'origine en premier"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Guide"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Guide de la vérification avant impression"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Fermer"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Qu'est-ce que la vérification avant impression ?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Un coup d'œil en lecture seule pour savoir si l'imprimante est prête à démarrer : elle ne déplace ni ne modifie jamais rien, elle se contente de signaler. Les blocages stricts font passer le verdict au rouge ; les avertissements informent mais ne bloquent pas."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Ce qu'elle vérifie"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper est prêt (ni arrêté ni en erreur), aucune impression n'est déjà en cours, et si les axes sont à l'origine (information, car un lancement d'impression effectue généralement la prise d'origine en premier)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossaire"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"État de Klipper"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Le statut propre à Klipper - 'ready' signifie qu'il est connecté et au repos ; 'shutdown' (arrêté) ou 'error' (erreur) signifie qu'il ne peut pas imprimer tant que ce n'est pas résolu."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"Prise d'origine"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Déplacer chaque axe jusqu'à son endstop (butée) afin que l'imprimante sache où se trouve la tête d'impression. La plupart des routines de lancement d'impression effectuent la prise d'origine automatiquement."}}}}}}};export{e as default};
